INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT159-S3-Q9$batch11$, 159, 3, 9, $batch11$Weaken$batch11$, $batch11$Having cameras at traffic intersections to automatically ticket cars that run red lights might raise revenue for municipalities but does not increase traffic safety. Accidents actually increase at intersections that have cameras: There are fewer side-impact collisions but significantly more rear-impact collisions.$batch11$, $batch11$Which one of the following, if true, most weakens the argument?$batch11$, $batch11$D$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$The revenue raised through automatically generated tickets can be used to address issues other than traffic safety.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Automatically generated tickets for running red lights have been shown to generate some undeserved tickets.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Side-impact collisions are generally the fault of the driver who drives through the red light.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Side-impact collisions are a much greater safety threat than rear-impact collisions.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$Automatically generated tickets can punish the owner of the car rather than the driver of the car at the time of the infraction.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Red-light cameras do not increase traffic safety.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Accidents go up at intersections with cameras. There are fewer side-impact crashes but significantly more rear-impact crashes.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The argument counts crashes but not how dangerous they are. Trading one type for another could still make roads safer if the type that drops is much worse.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show the crashes cameras prevent are far more dangerous than the ones they add.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$How revenue is spent doesn't change whether cameras improve safety.$batch11$), ($batch11$B$batch11$, $batch11$Undeserved tickets are a fairness problem, not a safety one.$batch11$), ($batch11$C$batch11$, $batch11$Who is at fault doesn't change how dangerous the crashes are.$batch11$), ($batch11$D$batch11$, $batch11$If side-impact crashes are far more dangerous, fewer of them can outweigh more rear-end crashes. Cameras could improve safety.$batch11$), ($batch11$E$batch11$, $batch11$Who gets punished doesn't affect safety.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT159-S3-Q9$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
